// Pega o CSV como texto do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // Normaliza minimo para numero
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// 1. Pega os clientes que vieram do Webhook
// (Você pode usar $items("Nome Exato Do Nó") para garantir que não se perde)
const clientes = $items("Conexão com o programa em python")[0].json.body.clientes || [];

// 2. Pega os investimentos que o seu nó "Parser Csv" já organizou!
const investimentos = $items("Parser Csv")[0].json.investimentos || [];

// Função para transformar "R$ 12.500,00" em número 12500
function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

const resultados = [];

// 3. Percorre cada cliente, cruza com os investimentos e cria a mensagem
for (const cliente of clientes) {
  const nomeCliente = cliente.nome || "";
  const emailCliente = cliente.email || "";
  const perfilCliente = cliente.perfil || "";
  const saldoTexto = cliente.saldo || "";
  const saldoNum = parseBRL(saldoTexto);

  // Encontra a opção de investimento que bate com o perfil E cabe no saldo
  const recomendacao = investimentos.find(inv => 
    inv.perfil.toLowerCase() === perfilCliente.toLowerCase() && saldoNum >= inv.minimo
  );

  if (recomendacao) {
    // AQUI você cria a mensagem personalizada para este cliente:
    const mensagem = `Olá ${nomeCliente}! Com base no seu perfil (${perfilCliente}), recomendamos a aplicação em **${recomendacao.produto}** (investimento mínimo de R$ ${recomendacao.minimo}). Com seu saldo disponível de ${saldoTexto}, você já pode começar a investir com rentabilidade estimada de ${recomendacao.rentabilidade}.`;

    resultados.push({
      nome: nomeCliente,
      email: emailCliente,
      perfil: perfilCliente,
      saldo_original: saldoTexto,
      saldo_numerico: saldoNum,
      produto_recomendado: recomendacao.produto,
      rentabilidade: recomendacao.rentabilidade,
      valor_minimo: recomendacao.minimo,
      mensagem_gerada: mensagem // <-- A mensagem personalizada pronta!
    });
  }
}

// 4. Retorna a lista final para o n8n
return resultados.map(resultado => ({ json: resultado }));

// Se veio dentro de .resultados usa ele; senão, pega TODOS os itens do nó anterior ($input.all())
const resultados = $json.resultados ? $json.resultados : $input.all().map(item => item.json);
function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo_original ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo_original ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao ?? c.produto_recomendado,
      motivo: c.motivo || "saldo_ok",
      mensagem_base: c.mensagem_escolhida || c.mensagem_gerada || c.mensagem || "",
      copy_rules: {
        idioma: "PT-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

