// 1. Puxa a lista de clientes do nó anterior à IA
// ATENÇÃO: Se o seu nó anterior tiver outro nome, coloque o nome exato dele aqui:
const clientesOriginais = $items("Merger do csv");

return $input.all().map((item, index) => {
  // Pega os dados originais do cliente correspondente
  const cliente = clientesOriginais[index]?.json || {};

  // 2. Função "radar": procura o texto gerado pela IA onde quer que ele esteja no JSON de saída
  function extrairTextoIA(obj) {
    if (typeof obj === 'string' && (obj.includes('"subject"') || obj.includes('subject'))) return obj;
    if (typeof obj === 'string' && obj.length > 20) return obj;
    if (typeof obj === 'object' && obj !== null) {
      for (let key in obj) {
        let res = extrairTextoIA(obj[key]);
        if (res) return res;
      }
    }
    return null;
  }

  // 3. Obtém o texto da IA
  let textoIA = extrairTextoIA(item.json) || item.json.text || item.json.response || "{}";
  let respostaIA = {};

  // 4. Limpa blocos de markdown ```json e faz o parse
  try {
    const textoLimpo = String(textoIA).replace(/```json/gi, '').replace(/```/g, '').trim();
    respostaIA = JSON.parse(textoLimpo);
  } catch (erro) {
    // Se a IA não devolveu em JSON puro, aproveita o texto diretamente
    respostaIA = {
      subject: `Oportunidade de Investimento - Perfil ${cliente.perfil || ""}`,
      text_body: textoIA,
      html_body: `<p>${textoIA}</p>`
    };
  }

  // 5. Monta o objeto final limpo e normalizado
  return {
    json: {
      ok: true,
      to: cliente.email_to || cliente.email || "",
      subject: respostaIA.subject || "",
      text_body: respostaIA.text_body || "",
      html_body: respostaIA.html_body || "",
      meta: {
        nome: cliente.nome,
        perfil: cliente.perfil,
        produto: cliente.recomendacao?.produto || cliente.recomendacao,
        saldo: cliente.saldo_texto || cliente.saldo_numerico
      }
    }
  };
});
